// Validate monotonic (non-decreasing) behavior across two reads
uint64_t t0 = _plat__RealTime();
uint64_t t1 = _plat__RealTime();
FUZZ_ASSERT(t1 >= t0, "_plat__RealTime must be non-decreasing");

// Constrain locality to a typical valid TPM range [0..4]
