uint32_t prev_hi = (uint32_t)FUZZ_GET_ATTR_INT_GLOBAL("timer_prev_hi");
uint64_t prev = ((uint64_t)prev_hi << 32) | prev_lo;
// If previous was set (non-zero) ensure non-decreasing
if (prev != 0) {
    FUZZ_ASSERT(now >= prev, "_plat__TimerRead must be monotonic (non-decreasing)");
}
// Update globals with current value
FUZZ_SET_ATTR_INT_GLOBAL("timer_prev_lo", (int)(now & 0xFFFFFFFFu));
FUZZ_SET_ATTR_INT_GLOBAL("timer_prev_hi", (int)((now >> 32) & 0xFFFFFFFFu));
// Validation: Enforces monotonicity property across invocations using global attributes.

// Reading this flag clears it before return per API
